export const RRB_JE_CBT2_TECHNICAL_MECHANICAL_1: Question[] = [
  { id: 'rrb-je-c2-mec-001', section: 'Technical Abilities', topic: 'Engineering Mechanics', difficulty: 'medium', question: 'A system of forces in which all the forces act in the same plane is called a:', options: ['Concurrent force system only', 'Coplanar force system', 'Spatial force system', 'Parallel force system only'], correctIndex: 1, explanation: 'A coplanar force system is one in which all the forces act within the same plane, as distinct from a spatial (non-coplanar) system, where forces act in three dimensions.', source },
  { id: 'rrb-je-c2-mec-002', section: 'Technical Abilities', topic: 'Engineering Mechanics', difficulty: 'medium', question: 'A set of forces that all pass through a single common point is called a:', options: ['Coplanar force system only', 'Concurrent force system', 'Non-concurrent force system', 'Couple'], correctIndex: 1, explanation: 'A concurrent force system consists of forces that all pass through (or whose lines of action intersect at) a single common point.', source },
  { id: 'rrb-je-c2-mec-003', section: 'Technical Abilities', topic: 'Engineering Mechanics', difficulty: 'medium', question: 'Two equal, parallel, and opposite forces, whose lines of action do not coincide, together produce a rotational effect known as a:', options: ['Resultant force', 'Couple', 'Moment of inertia', 'Equilibrant'], correctIndex: 1, explanation: 'A couple consists of two equal, parallel, and opposite forces whose lines of action do not coincide, producing a purely rotational effect (a moment) without any net translational force.', source },
  { id: 'rrb-je-c2-mec-004', section: 'Technical Abilities', topic: 'Engineering Mechanics', difficulty: 'medium', question: "According to Newton's Second Law of Motion, the rate of change of momentum of a body is directly proportional to:", options: ['The mass of the body alone', 'The applied external force, and acts in the direction of that force', 'The velocity of the body alone', 'The distance travelled by the body'], correctIndex: 1, explanation: "Newton's Second Law states that the rate of change of momentum of a body is directly proportional to the applied external force and takes place in the direction in which the force acts.", source },
  { id: 'rrb-je-c2-mec-005', section: 'Technical Abilities', topic: 'Engineering Mechanics', difficulty: 'medium', question: 'A single force that produces the same effect on a body as a given system of multiple forces acting together is called the:', options: ['Equilibrant', 'Resultant', 'Component force', 'Reactive force'], correctIndex: 1, explanation: 'The resultant is a single force that produces the same overall effect on a body as an entire system of multiple forces acting simultaneously.', source },
  { id: 'rrb-je-c2-mec-006', section: 'Technical Abilities', topic: 'Engineering Mechanics', difficulty: 'medium', question: 'A single force equal in magnitude but opposite in direction to the resultant of a system of forces, which brings the system into equilibrium, is called the:', options: ['Resultant', 'Equilibrant', 'Moment', 'Torque only'], correctIndex: 1, explanation: 'The equilibrant is a single force equal in magnitude but opposite in direction to the resultant of a force system, and its addition brings the entire system into a state of equilibrium.', source },
  { id: 'rrb-je-c2-mec-007', section: 'Technical Abilities', topic: 'Engineering Mechanics', difficulty: 'medium', question: 'The point at which the entire weight of a body may be considered to act, regardless of its orientation, is called the:', options: ['Centre of pressure', 'Centre of gravity', 'Metacentre', 'Point of application only'], correctIndex: 1, explanation: 'The centre of gravity of a body is the point at which its entire weight may be considered to act, irrespective of the orientation of the body.', source },
  { id: 'rrb-je-c2-mec-008', section: 'Technical Abilities', topic: 'Engineering Mechanics', difficulty: 'medium', question: 'The property of a body by virtue of which it resists any change in its state of rest or of uniform motion is called its:', options: ['Momentum', 'Inertia', 'Torque', 'Impulse only'], correctIndex: 1, explanation: 'Inertia is the inherent property of a body, related to its mass, by which it resists any change in its state of rest or uniform motion.', source },
  { id: 'rrb-je-c2-mec-009', section: 'Technical Abilities', topic: 'Engineering Mechanics', difficulty: 'medium', question: 'The turning effect (rotational tendency) produced by a force about a given point or axis is called:', options: ['Impulse', 'Moment (torque)', 'Momentum only', 'Work done, and nothing else'], correctIndex: 1, explanation: 'The moment (or torque) of a force about a point is the turning effect that the force produces about that point, calculated as the product of the force and the perpendicular distance from the point to the line of action of the force.', source },
  { id: 'rrb-je-c2-mec-010', section: 'Technical Abilities', topic: 'Engineering Mechanics', difficulty: 'medium', question: 'The product of the mass of a moving body and its velocity is called the:', options: ['Force', 'Momentum', 'Impulse only', 'Kinetic energy'], correctIndex: 1, explanation: 'Momentum is the product of the mass of a moving body and its velocity, and it is a vector quantity that indicates the quantity of motion possessed by the body.', source },
  { id: 'rrb-je-c2-mec-011', section: 'Technical Abilities', topic: 'Strength of Materials', difficulty: 'medium', question: 'The maximum stress up to which a material returns to its original shape and size completely upon removal of the applied load is called its:', options: ['Ultimate stress', 'Elastic limit', 'Yield point only', 'Breaking stress'], correctIndex: 1, explanation: 'The elastic limit is the maximum stress up to which a material behaves elastically, returning completely to its original shape and size once the applied load is removed.', source },
  { id: 'rrb-je-c2-mec-012', section: 'Technical Abilities', topic: 'Strength of Materials', difficulty: 'medium', question: 'The stress at which a material begins to deform plastically, showing a marked increase in strain (elongation) without a corresponding increase in stress, is called the:', options: ['Elastic limit', 'Yield point', 'Proof stress only', 'Fatigue limit'], correctIndex: 1, explanation: 'The yield point is the stress at which a material begins to deform plastically, exhibiting a marked increase in strain (elongation) without a proportional increase in applied stress.', source },
  { id: 'rrb-je-c2-mec-013', section: 'Technical Abilities', topic: 'Strength of Materials', difficulty: 'medium', question: 'The ratio of the maximum load a material can withstand to its original cross-sectional area, before it breaks, is called the:', options: ['Working stress', 'Ultimate tensile strength', 'Proof stress only', 'Factor of safety'], correctIndex: 1, explanation: 'Ultimate tensile strength is the ratio of the maximum load a material can withstand (under tension) to its original cross-sectional area, marking the peak point before the material breaks or necks significantly.', source },
  { id: 'rrb-je-c2-mec-014', section: 'Technical Abilities', topic: 'Strength of Materials', difficulty: 'medium', question: "The ratio of a material's ultimate stress to its permissible (working/allowable) stress, used to provide a margin of safety in design, is called the:", options: ['Modulus of elasticity', 'Factor of safety', 'Poisson\'s ratio', 'Modulus of rigidity'], correctIndex: 1, explanation: "The factor of safety is the ratio of a material's ultimate stress to its permissible (working) stress, providing a margin of safety to account for uncertainties in loading, material properties, and manufacturing.", source },
  { id: 'rrb-je-c2-mec-015', section: 'Technical Abilities', topic: 'Strength of Materials', difficulty: 'medium', question: 'The property of a material that measures its resistance to elastic shear deformation, relating shear stress to shear strain, is called the:', options: ["Young's modulus", 'Modulus of rigidity (shear modulus)', 'Bulk modulus', 'Poisson\'s ratio only'], correctIndex: 1, explanation: "The modulus of rigidity (shear modulus) measures a material's resistance to elastic shear deformation, relating shear stress to shear strain within the elastic limit.", source },
  { id: 'rrb-je-c2-mec-016', section: 'Technical Abilities', topic: 'Strength of Materials', difficulty: 'medium', question: 'A structural shaft subjected primarily to a twisting moment about its longitudinal axis is said to be under:', options: ['Bending', 'Torsion', 'Axial compression only', 'Shear only, and nothing else'], correctIndex: 1, explanation: 'Torsion refers to the twisting of a structural member, such as a shaft, caused by a torque (twisting moment) applied about its longitudinal axis.', source },
  { id: 'rrb-je-c2-mec-017', section: 'Technical Abilities', topic: 'Strength of Materials', difficulty: 'medium', question: 'A repeated, fluctuating load applied to a material over many cycles, which can eventually cause failure at a stress well below the material\'s ultimate strength, primarily causes:', options: ['Creep', 'Fatigue failure', 'Buckling only', 'Corrosion only'], correctIndex: 1, explanation: 'Fatigue failure occurs when a material is subjected to repeated, fluctuating loads over many cycles, causing failure at a stress level well below the material\'s ultimate (static) strength.', source },
  { id: 'rrb-je-c2-mec-018', section: 'Technical Abilities', topic: 'Strength of Materials', difficulty: 'medium', question: 'The gradual, time-dependent permanent deformation of a material under a constant (sustained) load, especially significant at elevated temperatures, is called:', options: ['Fatigue', 'Creep', 'Elastic recovery only', 'Strain hardening'], correctIndex: 1, explanation: 'Creep is the gradual, time-dependent permanent deformation of a material under a constant sustained load, and it becomes especially significant at elevated temperatures.', source },
  { id: 'rrb-je-c2-mec-019', section: 'Technical Abilities', topic: 'Strength of Materials', difficulty: 'medium', question: 'A slender structural column subjected to axial compressive load may fail suddenly by lateral bending/instability before the material\'s crushing (compressive) strength is reached; this mode of failure is called:', options: ['Fatigue failure', 'Buckling', 'Fracture only, and nothing else', 'Necking'], correctIndex: 1, explanation: 'Buckling is the sudden lateral bending/instability failure of a slender column under axial compressive load, occurring before the material\'s crushing (compressive) strength is actually reached.', source },
  { id: 'rrb-je-c2-mec-020', section: 'Technical Abilities', topic: 'Thermodynamics', difficulty: 'medium', question: 'The First Law of Thermodynamics is essentially a statement of the principle of conservation of:', options: ['Mass', 'Energy', 'Momentum only', 'Entropy'], correctIndex: 1, explanation: 'The First Law of Thermodynamics is a statement of the principle of conservation of energy, stating that energy can neither be created nor destroyed, only converted from one form to another.', source },
  { id: 'rrb-je-c2-mec-021', section: 'Technical Abilities', topic: 'Thermodynamics', difficulty: 'medium', question: 'The Second Law of Thermodynamics implies that heat cannot spontaneously flow from a:', options: ['Hotter body to a colder body', 'Colder body to a hotter body, without external work being done', 'Body to itself', 'Solid to a liquid'], correctIndex: 1, explanation: 'The Second Law of Thermodynamics (Clausius statement) implies that heat cannot spontaneously flow from a colder body to a hotter body without the input of external work, such as by a refrigerator or heat pump.', source },
  { id: 'rrb-je-c2-mec-022', section: 'Technical Abilities', topic: 'Thermodynamics', difficulty: 'medium', question: 'A thermodynamic process that occurs at a constant temperature is called a(n):', options: ['Adiabatic process', 'Isothermal process', 'Isochoric process only', 'Polytropic process'], correctIndex: 1, explanation: 'An isothermal process is a thermodynamic process that occurs at a constant temperature throughout, with the system in continuous thermal contact with its surroundings.', source },
  { id: 'rrb-je-c2-mec-023', section: 'Technical Abilities', topic: 'Thermodynamics', difficulty: 'medium', question: 'A thermodynamic process that occurs without any heat transfer between the system and its surroundings is called a(n):', options: ['Isothermal process', 'Adiabatic process', 'Isobaric process only', 'Isochoric process'], correctIndex: 1, explanation: 'An adiabatic process occurs with no heat transfer between the system and its surroundings; any change in internal energy in such a process is entirely due to work done on or by the system.', source },
  { id: 'rrb-je-c2-mec-024', section: 'Technical Abilities', topic: 'Thermodynamics', difficulty: 'medium', question: 'A thermodynamic process that occurs at a constant volume (with no change in volume) is called a(n):', options: ['Isobaric process', 'Isochoric (isometric) process', 'Isothermal process only', 'Adiabatic process'], correctIndex: 1, explanation: 'An isochoric (or isometric) process occurs at a constant volume, meaning no work is done by expansion or compression, so any heat added or removed changes only the internal energy of the system.', source },
  { id: 'rrb-je-c2-mec-025', section: 'Technical Abilities', topic: 'Thermodynamics', difficulty: 'medium', question: 'A thermodynamic process that occurs at a constant pressure is called a(n):', options: ['Isochoric process', 'Isobaric process', 'Isothermal process only', 'Adiabatic process, and nothing else'], correctIndex: 1, explanation: 'An isobaric process occurs at a constant pressure throughout, such as heat addition to a gas in a cylinder with a freely moving piston maintaining constant pressure.', source },
  { id: 'rrb-je-c2-mec-026', section: 'Technical Abilities', topic: 'Thermodynamics', difficulty: 'medium', question: 'The measure of the degree of molecular disorder (randomness) of a thermodynamic system, which, according to the Second Law, tends to increase in any spontaneous (irreversible) process of an isolated system, is called:', options: ['Enthalpy', 'Internal energy only', 'Specific heat', 'Entropy'], correctIndex: 3, explanation: 'Entropy is a thermodynamic property that measures the degree of molecular disorder (randomness) of a system, and it tends to increase in any spontaneous, irreversible process occurring within an isolated system.', source },
  { id: 'rrb-je-c2-mec-027', section: 'Technical Abilities', topic: 'Thermodynamics', difficulty: 'medium', question: 'The sum of the internal energy of a system and the product of its pressure and volume (a useful property for flow processes) is called:', options: ['Entropy', 'Free energy only', 'Enthalpy', 'Specific volume'], correctIndex: 2, explanation: 'Enthalpy is defined as the sum of the internal energy of a system and the product of its pressure and volume (H = U + PV), and it is a particularly useful property for analysing flow (open system) thermodynamic processes.', source },
  { id: 'rrb-je-c2-mec-028', section: 'Technical Abilities', topic: 'IC Engines', difficulty: 'medium', question: 'An internal combustion engine that ignites its air-fuel mixture using a spark plug (rather than solely through compression heat) is generally called a(n):', options: ['Spark Ignition (SI) engine', 'Compression Ignition (CI) engine', 'External combustion engine', 'Gas turbine only'], correctIndex: 0, explanation: 'A Spark Ignition (SI) engine, such as a typical petrol/gasoline engine, ignites its air-fuel mixture using a spark plug, as distinct from a Compression Ignition (CI) engine (diesel), which relies on the heat generated by high compression.', source },
  { id: 'rrb-je-c2-mec-029', section: 'Technical Abilities', topic: 'IC Engines', difficulty: 'medium', question: 'An internal combustion engine (typically a diesel engine) that ignites its fuel purely through the heat generated by the high compression of air, without a spark plug, is generally called a(n):', options: ['Spark Ignition (SI) engine', 'Two-stroke petrol engine only', 'External combustion engine', 'Compression Ignition (CI) engine'], correctIndex: 3, explanation: 'A Compression Ignition (CI) engine, typically a diesel engine, ignites its fuel through the heat generated by highly compressing air in the cylinder, without requiring a spark plug.', source },
  { id: 'rrb-je-c2-mec-030', section: 'Technical Abilities', topic: 'IC Engines', difficulty: 'medium', question: 'In a four-stroke IC engine, the four strokes of the piston, in order, are:', options: ['Power, Compression, Suction, Exhaust', 'Exhaust, Suction, Power, Compression', 'Suction, Compression, Power (Expansion), Exhaust', 'Compression, Suction, Exhaust, Power'], correctIndex: 2, explanation: 'The four strokes of a four-stroke IC engine occur in the order: Suction (intake), Compression, Power (expansion, following combustion), and Exhaust.', source },
  { id: 'rrb-je-c2-mec-031', section: 'Technical Abilities', topic: 'IC Engines', difficulty: 'medium', question: 'A two-stroke IC engine, compared to a four-stroke engine of similar size, completes its full working cycle (suction, compression, power, exhaust functions) in:', options: ['Two strokes of the piston (one crankshaft revolution)', 'Four strokes of the piston (two crankshaft revolutions)', 'Six strokes of the piston', 'One stroke of the piston'], correctIndex: 0, explanation: 'A two-stroke IC engine completes its full working cycle in just two strokes of the piston (one revolution of the crankshaft), compared to the four strokes (two revolutions) required by a four-stroke engine.', source },
  { id: 'rrb-je-c2-mec-032', section: 'Technical Abilities', topic: 'IC Engines', difficulty: 'medium', question: 'The ratio of the total volume of the cylinder (with the piston at the bottom of its stroke) to the clearance volume (with the piston at the top of its stroke) in an IC engine is called the:', options: ['Volumetric efficiency', 'Air-fuel ratio only', 'Mechanical efficiency', 'Compression ratio'], correctIndex: 3, explanation: 'The compression ratio of an IC engine is the ratio of the total cylinder volume (piston at bottom dead centre) to the clearance volume (piston at top dead centre), and it significantly influences the engine\'s thermal efficiency.', source },
  { id: 'rrb-je-c2-mec-033', section: 'Technical Abilities', topic: 'IC Engines', difficulty: 'medium', question: 'The device in a spark-ignition petrol engine responsible for mixing air and fuel in the correct proportion before it enters the combustion chamber (in older, non-fuel-injected engines) is called the:', options: ['Fuel injector only', 'Turbocharger', 'Carburettor', 'Radiator'], correctIndex: 2, explanation: 'A carburettor is a device in older spark-ignition petrol engines that mixes air and fuel in the correct proportion before the mixture enters the combustion chamber, a function now largely performed by electronic fuel injection in modern engines.', source },
  { id: 'rrb-je-c2-mec-034', section: 'Technical Abilities', topic: 'IC Engines', difficulty: 'medium', question: 'The device fitted to an IC engine to reduce the noise produced by the exhaust gases as they are released to the atmosphere is called the:', options: ['Silencer (muffler)', 'Radiator', 'Carburettor only', 'Flywheel'], correctIndex: 0, explanation: 'A silencer (muffler) is fitted in the exhaust system of an IC engine to reduce the noise produced by the exhaust gases as they are expelled to the atmosphere.', source },
  { id: 'rrb-je-c2-mec-035', section: 'Technical Abilities', topic: 'IC Engines', difficulty: 'medium', question: 'A heavy rotating wheel fitted to the crankshaft of an IC engine, which stores kinetic energy during the power stroke and releases it during the other strokes, thereby smoothing out fluctuations in engine speed, is called the:', options: ['Camshaft', 'Crankshaft only, and nothing else', 'Piston', 'Flywheel'], correctIndex: 3, explanation: 'A flywheel is a heavy rotating wheel fitted to the crankshaft, storing kinetic energy during the power stroke and releasing it during the other strokes, thereby smoothing out fluctuations in engine speed.', source },
  { id: 'rrb-je-c2-mec-036', section: 'Technical Abilities', topic: 'Theory of Machines', difficulty: 'medium', question: 'An assembly of a number of rigid bodies (links) connected by joints, arranged so that relative motion between the links is possible, is called a:', options: ['Structure', 'Machine element only, exclusively', 'Mechanism', 'Kinematic pair, and only that'], correctIndex: 2, explanation: 'A mechanism is an assembly of rigid bodies (links) connected by joints in such a way that relative motion between the links is possible, forming the basic building block of machines.', source },
  { id: 'rrb-je-c2-mec-037', section: 'Technical Abilities', topic: 'Theory of Machines', difficulty: 'medium', question: 'A connection between two links that permits relative motion between them, such as a pin joint or a sliding joint, is called a:', options: ['Kinematic pair', 'Kinematic chain only', 'Mechanism only, and nothing else', 'Degree of freedom'], correctIndex: 0, explanation: 'A kinematic pair is a connection between two links of a mechanism that permits relative motion between them, such as a pin joint (revolute pair) or a sliding joint (prismatic pair).', source },
  { id: 'rrb-je-c2-mec-038', section: 'Technical Abilities', topic: 'Theory of Machines', difficulty: 'medium', question: 'A four-bar mechanism in which the shortest link is fixed, and both of the links adjacent to it can rotate completely, is called a:', options: ['Double rocker mechanism', 'Crank-rocker mechanism', 'Double crank mechanism', 'Any mechanism, without any specific classification'], correctIndex: 2, explanation: 'In a four-bar mechanism, when the shortest link is fixed (as the frame), both adjacent links can rotate completely, resulting in a double crank mechanism (also called a "drag-link" mechanism).', source },
  { id: 'rrb-je-c2-mec-039', section: 'Technical Abilities', topic: 'Theory of Machines', difficulty: 'medium', question: 'A mechanical device used to transmit rotary motion and power between two shafts through direct contact of toothed wheels is called a:', options: ['Belt drive', 'Chain drive only', 'Coupling only', 'Gear'], correctIndex: 3, explanation: 'A gear is a toothed mechanical component that transmits rotary motion and power between two shafts through direct meshing contact of the teeth, offering a positive (non-slip) drive.', source },
  { id: 'rrb-je-c2-mec-040', section: 'Technical Abilities', topic: 'Theory of Machines', difficulty: 'medium', question: 'A mechanical device used to store energy (typically by twisting or compression/extension) and release it gradually, commonly used for cushioning shocks or maintaining continuous force, is called a:', options: ['Gear', 'Bearing only, exclusively', 'Spring', 'Cam only'], correctIndex: 2, explanation: 'A spring is a mechanical device designed to deform elastically (by twisting, compression, or extension) under load, storing energy and releasing it gradually, commonly used for cushioning shocks, absorbing vibration, or maintaining a continuous force.', source },
  { id: 'rrb-je-c2-mec-041', section: 'Technical Abilities', topic: 'Theory of Machines', difficulty: 'medium', question: 'A rotating machine element used to support a rotating shaft and reduce friction between the shaft and its housing is called a:', options: ['Bearing', 'Coupling', 'Flywheel only', 'Cam only'], correctIndex: 0, explanation: 'A bearing is a machine element used to support a rotating (or sliding) shaft, reducing friction between the moving shaft and its stationary housing, and it may be a plain (sliding) bearing or a rolling-element (ball/roller) bearing.', source },
  { id: 'rrb-je-c2-mec-042', section: 'Technical Abilities', topic: 'Theory of Machines', difficulty: 'medium', question: 'A device used to connect two rotating shafts (typically end to end, in the same line) so that they rotate together and transmit power/torque from one to the other, is called a:', options: ['Bearing', 'Clutch only, exclusively', 'Cam', 'Coupling'], correctIndex: 3, explanation: 'A coupling is a mechanical device used to connect two rotating shafts, typically end to end and aligned along the same axis, so that they rotate together and transmit power/torque from one shaft to the other.', source },
  { id: 'rrb-je-c2-mec-043', section: 'Technical Abilities', topic: 'Theory of Machines', difficulty: 'medium', question: 'A mechanical device that allows the driving shaft to be engaged or disengaged from the driven shaft at will, commonly used in vehicles to interrupt power transmission from the engine to the gearbox, is called a:', options: ['Coupling', 'Bearing only, and nothing else', 'Clutch', 'Universal joint only'], correctIndex: 2, explanation: 'A clutch is a mechanical device that allows the driving shaft to be engaged or disengaged from the driven shaft at will, commonly used in vehicles to interrupt power transmission from the engine to the gearbox during gear changes.', source },
  { id: 'rrb-je-c2-mec-044', section: 'Technical Abilities', topic: 'Theory of Machines', difficulty: 'medium', question: 'A rotating machine element with an irregularly shaped profile, used to convert rotary motion into a specific, often reciprocating or oscillating, output motion of a follower, is called a:', options: ['Cam', 'Gear', 'Flywheel only', 'Crankshaft, and nothing else'], correctIndex: 0, explanation: 'A cam is a rotating machine element with an irregularly shaped profile, designed to convert rotary motion into a specific reciprocating, oscillating, or other prescribed output motion of a follower that rests on (or is constrained to) its profile.', source },
  { id: 'rrb-je-c2-mec-045', section: 'Technical Abilities', topic: 'Fluid Mechanics and Hydraulic Machines', difficulty: 'medium', question: 'A rotating hydraulic machine that converts the kinetic and pressure energy of flowing water into mechanical (rotational) energy, commonly used in hydroelectric power plants, is called a:', options: ['Pump', 'Compressor only, exclusively', 'Fan, and nothing else', 'Turbine'], correctIndex: 3, explanation: 'A turbine is a rotating hydraulic machine that converts the kinetic and pressure energy of flowing water into mechanical (rotational) energy, most commonly used to drive electrical generators in hydroelectric power plants.', source },
  { id: 'rrb-je-c2-mec-046', section: 'Technical Abilities', topic: 'Fluid Mechanics and Hydraulic Machines', difficulty: 'medium', question: 'A hydraulic turbine that operates fully submerged, with water under pressure acting on the runner blades throughout, and generally used for medium to low heads with high flow rates, is classified as a(n):', options: ['Impulse turbine', 'Gas turbine only', 'Reaction turbine', 'Steam turbine, and nothing else'], correctIndex: 2, explanation: 'A reaction turbine operates fully submerged, with water under pressure acting on the runner blades continuously as it passes through, and is generally suited to medium-to-low heads with relatively high flow rates (e.g., the Francis and Kaplan turbines).', source },
  { id: 'rrb-je-c2-mec-047', section: 'Technical Abilities', topic: 'Fluid Mechanics and Hydraulic Machines', difficulty: 'medium', question: 'A hydraulic turbine in which a high-velocity jet of water strikes the buckets of a freely rotating wheel at atmospheric pressure, converting the water\'s kinetic energy into mechanical work, is classified as a(n):', options: ['Impulse turbine', 'Reaction turbine', 'Centrifugal pump only', 'Reciprocating pump, and nothing else'], correctIndex: 0, explanation: 'An impulse turbine (such as the Pelton wheel) operates with a high-velocity jet of water striking the buckets of a freely rotating wheel at atmospheric pressure, converting the kinetic energy of the jet into mechanical work; it is typically used for high-head, low-flow situations.', source },
  { id: 'rrb-je-c2-mec-048', section: 'Technical Abilities', topic: 'Fluid Mechanics and Hydraulic Machines', difficulty: 'medium', question: 'A pump that raises fluid using the centrifugal force generated by a rotating impeller, converting mechanical energy into pressure and kinetic energy of the fluid, is called a:', options: ['Reciprocating pump', 'Gear pump only', 'Vacuum pump, exclusively', 'Centrifugal pump'], correctIndex: 3, explanation: 'A centrifugal pump uses the centrifugal force generated by a rotating impeller to raise/move fluid, converting the mechanical energy of the rotating impeller into pressure and kinetic energy of the fluid.', source },
  { id: 'rrb-je-c2-mec-049', section: 'Technical Abilities', topic: 'Fluid Mechanics and Hydraulic Machines', difficulty: 'medium', question: 'A positive-displacement pump that draws and delivers fluid through the reciprocating (back-and-forth) motion of a piston or plunger within a cylinder is called a:', options: ['Centrifugal pump', 'Axial flow pump only', 'Reciprocating pump', 'Jet pump, exclusively'], correctIndex: 2, explanation: 'A reciprocating pump is a positive-displacement pump that draws and delivers fluid through the reciprocating (back-and-forth) motion of a piston or plunger inside a cylinder, fitted with suction and delivery valves.', source },
  { id: 'rrb-je-c2-mec-050', section: 'Technical Abilities', topic: 'Fluid Mechanics and Hydraulic Machines', difficulty: 'medium', question: 'A machine used to increase the pressure of a gas (typically air) by reducing its volume through mechanical work is called a:', options: ['Compressor', 'Turbine', 'Condenser only', 'Evaporator, exclusively'], correctIndex: 0, explanation: 'A compressor is a machine used to increase the pressure of a gas (most commonly air) by mechanically reducing its volume, and it is widely used in pneumatic systems, refrigeration, and industrial applications.', source },
  { id: 'rrb-je-c2-mec-051', section: 'Technical Abilities', topic: 'Production Engineering', difficulty: 'medium', question: 'A manufacturing process in which molten metal is poured into a mould cavity and allowed to solidify into the desired shape is called:', options: ['Forging', 'Welding only', 'Machining, exclusively', 'Casting'], correctIndex: 3, explanation: 'Casting is a manufacturing process in which molten metal is poured into a mould cavity of the desired shape and allowed to solidify, after which the mould is removed to reveal the cast component.', source },
  { id: 'rrb-je-c2-mec-052', section: 'Technical Abilities', topic: 'Production Engineering', difficulty: 'medium', question: 'A manufacturing process in which a metal workpiece is shaped by applying compressive forces (typically by hammering or pressing), usually while heated, to plastically deform it into the desired shape, is called:', options: ['Casting', 'Rolling only', 'Forging', 'Extrusion, exclusively'], correctIndex: 2, explanation: 'Forging is a manufacturing process in which a metal workpiece is plastically deformed into the desired shape by applying compressive forces (through hammering or pressing), typically while the metal is heated for improved workability.', source },
  { id: 'rrb-je-c2-mec-053', section: 'Technical Abilities', topic: 'Production Engineering', difficulty: 'medium', question: 'A metal-joining process in which two or more pieces of metal are permanently joined together, typically by applying heat (and sometimes pressure), causing coalescence at the joint, is called:', options: ['Welding', 'Riveting', 'Bolting only', 'Soldering only, exclusively'], correctIndex: 0, explanation: 'Welding is a metal-joining process in which two or more pieces of metal are permanently joined by applying heat (and sometimes pressure), causing coalescence (fusion) at the joint.', source },
  { id: 'rrb-je-c2-mec-054', section: 'Technical Abilities', topic: 'Production Engineering', difficulty: 'medium', question: 'A machine tool used to remove material from a rotating cylindrical workpiece by moving a cutting tool along its surface, commonly used to produce cylindrical, tapered, or threaded components, is called a:', options: ['Milling machine', 'Drilling machine only', 'Shaper, exclusively', 'Lathe'], correctIndex: 3, explanation: 'A lathe is a machine tool that rotates a workpiece against a stationary (linearly moving) cutting tool to remove material, commonly used to produce cylindrical, tapered, or threaded components.', source },
  { id: 'rrb-je-c2-mec-055', section: 'Technical Abilities', topic: 'Production Engineering', difficulty: 'medium', question: 'A machine tool that uses a rotating multi-point cutting tool to remove material from a stationary (or fed) workpiece, commonly used to produce flat surfaces, slots, and complex profiles, is called a:', options: ['Lathe', 'Grinding machine only', 'Milling machine', 'Planer, exclusively'], correctIndex: 2, explanation: 'A milling machine uses a rotating multi-point cutting tool (a milling cutter) to remove material from a stationary or fed workpiece, commonly used to produce flat surfaces, slots, gears, and other complex profiles.', source },
  { id: 'rrb-je-c2-mec-056', section: 'Technical Abilities', topic: 'Production Engineering', difficulty: 'medium', question: 'A machining process that uses an abrasive wheel to remove small amounts of material from a workpiece, primarily to achieve a fine surface finish and precise dimensional accuracy, is called:', options: ['Grinding', 'Milling', 'Drilling only', 'Planing, exclusively'], correctIndex: 0, explanation: 'Grinding is a machining process that uses an abrasive wheel to remove small amounts of material from a workpiece, primarily to achieve a fine surface finish and precise dimensional accuracy.', source },
  { id: 'rrb-je-c2-mec-057', section: 'Technical Abilities', topic: 'Production Engineering', difficulty: 'medium', question: 'A machining process that uses a rotating multi-point cutting tool to produce cylindrical holes in a workpiece is called:', options: ['Milling', 'Turning only', 'Reaming, exclusively (drilling excluded)', 'Drilling'], correctIndex: 3, explanation: 'Drilling is a machining process that uses a rotating multi-point cutting tool (a drill bit) to produce cylindrical holes in a workpiece.', source },
  { id: 'rrb-je-c2-mec-058', section: 'Technical Abilities', topic: 'Production Engineering', difficulty: 'medium', question: 'A metal-forming process in which a metal billet (or ingot) is heated and compressed to reduce its thickness and increase its length, commonly used to produce plates, sheets, and structural sections, is called:', options: ['Extrusion', 'Drawing only', 'Rolling', 'Spinning, exclusively'], correctIndex: 2, explanation: 'Rolling is a metal-forming process in which a heated metal billet is passed between rotating rolls, reducing its thickness and increasing its length, commonly used to produce plates, sheets, and structural sections.', source },
  { id: 'rrb-je-c2-mec-059', section: 'Technical Abilities', topic: 'Production Engineering', difficulty: 'medium', question: 'A metal-forming process in which a heated metal billet is forced (pushed) through a die of a desired cross-sectional shape to produce a long product of that constant cross-section, is called:', options: ['Extrusion', 'Rolling', 'Forging only', 'Drawing, exclusively'], correctIndex: 0, explanation: 'Extrusion is a metal-forming process in which a heated metal billet is forced through a die of a desired cross-sectional shape, producing a long product with a constant cross-section, such as rods, tubes, and structural profiles.', source },
  { id: 'rrb-je-c2-mec-060', section: 'Technical Abilities', topic: 'Production Engineering', difficulty: 'medium', question: 'A joining process using two smooth-bore metal pieces fastened permanently by inserting a metal pin through aligned holes and then forming a head on both ends (typically by hammering), commonly used before welding became widespread, is called:', options: ['Welding', 'Brazing only', 'Bolting, exclusively', 'Riveting'], correctIndex: 3, explanation: 'Riveting is a permanent mechanical joining process in which a metal pin (rivet) is inserted through aligned holes in the parts to be joined, and a head is then formed on both ends (typically by hammering or pressing), historically widespread before welding became common.', source },
  { id: 'rrb-je-c2-mec-061', section: 'Technical Abilities', topic: 'Refrigeration and Air Conditioning', difficulty: 'medium', question: 'The process of removing heat from an enclosed space or substance, thereby lowering and maintaining its temperature below that of the surroundings, is called:', options: ['Combustion', 'Distillation only, exclusively', 'Refrigeration', 'Sublimation, and nothing else'], correctIndex: 2, explanation: 'Refrigeration is the process of removing heat from an enclosed space or substance, thereby lowering and maintaining its temperature below that of the surrounding environment.', source },
  { id: 'rrb-je-c2-mec-062', section: 'Technical Abilities', topic: 'Refrigeration and Air Conditioning', difficulty: 'medium', question: 'In a standard vapour compression refrigeration cycle, the component responsible for raising the pressure and temperature of the low-pressure refrigerant vapour before it enters the condenser is called the:', options: ['Compressor', 'Evaporator', 'Expansion (throttle) valve only', 'Condenser, and nothing else'], correctIndex: 0, explanation: 'In a vapour compression refrigeration cycle, the compressor raises the pressure and temperature of the low-pressure refrigerant vapour received from the evaporator, before delivering it to the condenser.', source },
  { id: 'rrb-je-c2-mec-063', section: 'Technical Abilities', topic: 'Refrigeration and Air Conditioning', difficulty: 'medium', question: 'In a vapour compression refrigeration cycle, the component in which the refrigerant absorbs heat from the space or substance to be cooled, evaporating in the process, is called the:', options: ['Condenser', 'Compressor only', 'Expansion valve, and nothing else', 'Evaporator'], correctIndex: 3, explanation: 'The evaporator is the component of a vapour compression refrigeration cycle in which the low-pressure liquid refrigerant absorbs heat from the space or substance being cooled, evaporating into a low-pressure vapour in the process.', source },
  { id: 'rrb-je-c2-mec-064', section: 'Technical Abilities', topic: 'Refrigeration and Air Conditioning', difficulty: 'medium', question: 'In a vapour compression refrigeration cycle, the component in which the high-pressure refrigerant vapour rejects heat to the surrounding medium (such as air or water) and condenses into a liquid, is called the:', options: ['Evaporator', 'Compressor only, exclusively', 'Condenser', 'Receiver, and nothing else'], correctIndex: 2, explanation: 'The condenser is the component of a vapour compression refrigeration cycle in which the high-pressure refrigerant vapour, received from the compressor, rejects heat to the surrounding medium and condenses into a high-pressure liquid.', source },
  { id: 'rrb-je-c2-mec-065', section: 'Technical Abilities', topic: 'Refrigeration and Air Conditioning', difficulty: 'medium', question: 'In a vapour compression refrigeration cycle, the component that reduces the pressure and temperature of the high-pressure liquid refrigerant before it enters the evaporator is called the:', options: ['Expansion (throttle) valve', 'Compressor', 'Condenser only, exclusively', 'Accumulator, and nothing else'], correctIndex: 0, explanation: 'The expansion (throttle) valve reduces the pressure and temperature of the high-pressure liquid refrigerant, received from the condenser, before it enters the evaporator at low pressure.', source },
  { id: 'rrb-je-c2-mec-066', section: 'Technical Abilities', topic: 'Refrigeration and Air Conditioning', difficulty: 'medium', question: 'The ratio of the refrigerating effect (heat extracted) produced to the work input required to produce it, used as a measure of the performance of a refrigeration system, is called the:', options: ['Volumetric efficiency', 'Thermal efficiency only', 'Relative humidity, exclusively', 'Coefficient of Performance (COP)'], correctIndex: 3, explanation: 'The Coefficient of Performance (COP) is the ratio of the refrigerating effect (heat extracted from the cooled space) produced to the work input required to produce it, and it is used as the key measure of a refrigeration system\'s performance.', source },
  { id: 'rrb-je-c2-mec-067', section: 'Technical Abilities', topic: 'Refrigeration and Air Conditioning', difficulty: 'medium', question: 'The amount of water vapour actually present in a given mass of air, expressed as a percentage of the maximum amount of water vapour the air could hold at that same temperature, is called the:', options: ['Specific humidity', 'Dew point only, and nothing else', 'Relative humidity', 'Wet bulb depression, exclusively'], correctIndex: 2, explanation: 'Relative humidity is the amount of water vapour actually present in a given mass of air, expressed as a percentage of the maximum amount of water vapour that air could hold at the same temperature (i.e., its saturation capacity).', source },
  { id: 'rrb-je-c2-mec-068', section: 'Technical Abilities', topic: 'Refrigeration and Air Conditioning', difficulty: 'medium', question: 'The temperature at which air, when cooled at constant pressure without changing its moisture content, becomes fully saturated and water vapour begins to condense, is called the:', options: ['Dew point temperature', 'Wet bulb temperature', 'Dry bulb temperature only', 'Sensible heat temperature, exclusively'], correctIndex: 0, explanation: 'The dew point temperature is the temperature at which air, cooled at constant pressure without any change in moisture content, becomes fully saturated, causing water vapour to begin condensing.', source },
  { id: 'rrb-je-c2-mec-069', section: 'Technical Abilities', topic: 'Engineering Mechanics', difficulty: 'medium', question: 'A body is said to be in a state of static equilibrium when the resultant of all the forces (and moments) acting on it is:', options: ['Maximum', 'Equal to its weight only', 'Always positive, and never zero', 'Zero'], correctIndex: 3, explanation: 'A body is in static equilibrium when the resultant of all the forces and moments acting on it is zero, meaning it has no tendency to translate or rotate.', source },
  { id: 'rrb-je-c2-mec-070', section: 'Technical Abilities', topic: 'Engineering Mechanics', difficulty: 'medium', question: 'The unit of work and energy in the SI system is the:', options: ['Newton', 'Watt only', 'Joule', 'Pascal, exclusively'], correctIndex: 2, explanation: 'The Joule is the SI unit of work and energy, defined as the work done when a force of one Newton displaces its point of application by one metre in the direction of the force.', source },
  { id: 'rrb-je-c2-mec-071', section: 'Technical Abilities', topic: 'Engineering Mechanics', difficulty: 'medium', question: 'The SI unit of power, defined as the rate of doing work of one Joule per second, is the:', options: ['Newton', 'Joule', 'Watt', 'Pascal, and nothing else'], correctIndex: 2, explanation: 'The Watt is the SI unit of power, defined as the rate of doing work of one Joule per second.', source },
  { id: 'rrb-je-c2-mec-072', section: 'Technical Abilities', topic: 'Strength of Materials', difficulty: 'medium', question: 'When a body is subjected to equal stress in three mutually perpendicular directions (such as a body under uniform hydrostatic pressure), the ratio of the direct stress to the corresponding volumetric strain is called the:', options: ['Bulk modulus', "Young's modulus", 'Modulus of rigidity only', "Poisson's ratio, exclusively"], correctIndex: 0, explanation: 'The Bulk modulus is the ratio of the direct (uniform) stress applied to a body in three mutually perpendicular directions to the corresponding volumetric strain, describing the material\'s resistance to uniform compression.', source },
  { id: 'rrb-je-c2-mec-073', section: 'Technical Abilities', topic: 'Strength of Materials', difficulty: 'medium', question: 'The property of a material that measures its ability to absorb energy (without permanent deformation) up to its elastic limit is called its:', options: ['Toughness', 'Hardness only', 'Ductility, exclusively', 'Resilience'], correctIndex: 3, explanation: "Resilience is a material's ability to absorb energy elastically (without permanent deformation) up to its elastic limit, and it is recovered fully once the applied load is removed.", source },
  { id: 'rrb-je-c2-mec-074', section: 'Technical Abilities', topic: 'Strength of Materials', difficulty: 'medium', question: 'The property of a material that describes its ability to absorb energy and undergo plastic deformation before it finally fractures (including energy absorbed beyond the elastic limit) is called its:', options: ['Resilience', 'Stiffness only', 'Toughness', 'Malleability, exclusively'], correctIndex: 2, explanation: "Toughness is a material's ability to absorb energy and undergo plastic deformation before it finally fractures, encompassing energy absorption both within and beyond the elastic limit, unlike resilience which is limited to the elastic range alone.", source },
  { id: 'rrb-je-c2-mec-075', section: 'Technical Abilities', topic: 'Strength of Materials', difficulty: 'medium', question: 'The resistance offered by a material to indentation, scratching, abrasion, or cutting by another harder body is called its:', options: ['Hardness', 'Toughness', 'Elasticity only', 'Ductility, and nothing else'], correctIndex: 0, explanation: 'Hardness is the resistance a material offers to indentation, scratching, abrasion, or cutting by another harder body, commonly measured using tests such as Brinell, Rockwell, or Vickers hardness testing.', source },
  { id: 'rrb-je-c2-mec-076', section: 'Technical Abilities', topic: 'Thermodynamics', difficulty: 'medium', question: 'The amount of heat energy required to raise the temperature of a unit mass of a substance by one degree (Celsius or Kelvin) is called its:', options: ['Latent heat', 'Enthalpy only', 'Calorific value, exclusively', 'Specific heat'], correctIndex: 3, explanation: 'Specific heat is the amount of heat energy required to raise the temperature of a unit mass of a substance by one degree (Celsius or Kelvin).', source },
  { id: 'rrb-je-c2-mec-077', section: 'Technical Abilities', topic: 'Thermodynamics', difficulty: 'medium', question: 'The amount of heat energy absorbed or released by a substance during a change of phase (such as melting or boiling) at a constant temperature, without any accompanying change in temperature, is called:', options: ['Sensible heat', 'Specific heat only', 'Latent heat', 'Enthalpy, and nothing else'], correctIndex: 2, explanation: 'Latent heat is the heat energy absorbed or released by a substance during a change of phase (such as melting or boiling), occurring at a constant temperature, unlike sensible heat, which causes a measurable temperature change.', source },
  { id: 'rrb-je-c2-mec-078', section: 'Technical Abilities', topic: 'Thermodynamics', difficulty: 'medium', question: 'A heat exchanger device used in an IC engine cooling system to dissipate excess heat from the engine coolant to the surrounding atmosphere is called the:', options: ['Radiator', 'Condenser', 'Evaporator only, exclusively', 'Compressor, and nothing else'], correctIndex: 0, explanation: 'The radiator is a heat exchanger device in an IC engine cooling system that dissipates excess heat from the circulating engine coolant to the surrounding atmosphere, typically with the help of a fan.', source },
  { id: 'rrb-je-c2-mec-079', section: 'Technical Abilities', topic: 'Theory of Machines', difficulty: 'medium', question: 'The undesirable phenomenon of unbalanced, vibratory to-and-fro motion of a mechanical system about its equilibrium position, often caused by unbalanced rotating or reciprocating masses, is called:', options: ['Torque', 'Inertia only', 'Momentum, exclusively', 'Vibration'], correctIndex: 3, explanation: 'Vibration is the oscillatory (to-and-fro) motion of a mechanical system about its equilibrium position, often caused by unbalanced rotating or reciprocating masses, and it is generally undesirable in machinery due to noise, wear, and fatigue effects.', source },
  { id: 'rrb-je-c2-mec-080', section: 'Technical Abilities', topic: 'Theory of Machines', difficulty: 'medium', question: 'A flexible mechanical element (typically made of rubber, leather, or fabric) used to transmit power between two shafts fitted with pulleys, relying on friction between the element and the pulley surface, is called a:', options: ['Chain', 'Gear only, exclusively', 'Belt', 'Coupling, and nothing else'], correctIndex: 2, explanation: 'A belt is a flexible mechanical element used to transmit power between two shafts fitted with pulleys, relying on the friction developed between the belt and the pulley surfaces, as distinct from a chain drive, which uses a positive, non-slip meshing engagement.', source },
  { id: 'rrb-je-c2-mec-081', section: 'Technical Abilities', topic: 'Theory of Machines', difficulty: 'medium', question: 'A flexible mechanical power-transmission element consisting of a series of interconnected links, engaging with toothed sprocket wheels to provide a positive (non-slip) drive between two shafts, is called a:', options: ['Chain', 'Belt', 'Rope drive only, exclusively', 'V-belt, and nothing else'], correctIndex: 0, explanation: 'A chain is a flexible power-transmission element consisting of interconnected links that engage with toothed sprocket wheels, providing a positive, non-slip drive between two shafts (unlike a belt, which relies on friction).', source },
  { id: 'rrb-je-c2-mec-082', section: 'Technical Abilities', topic: 'Production Engineering', difficulty: 'medium', question: 'A destructive testing method used to determine the hardness of a metal by measuring the depth of penetration of a diamond or ball indenter under a specified load is generally called the:', options: ['Tensile test', 'Impact test only, exclusively', 'Fatigue test, and nothing else', 'Rockwell (or Brinell/Vickers) hardness test'], correctIndex: 3, explanation: 'Hardness testing methods such as the Rockwell, Brinell, and Vickers tests determine the hardness of a metal by measuring the depth or size of the indentation made by a diamond or ball indenter under a specified applied load.', source },
  { id: 'rrb-je-c2-mec-083', section: 'Technical Abilities', topic: 'Production Engineering', difficulty: 'medium', question: 'A mechanical testing method used to determine the impact resistance (toughness) of a material by measuring the energy absorbed in fracturing a notched specimen with a swinging pendulum hammer is called the:', options: ['Tensile test only', 'Fatigue test only, exclusively', 'Izod/Charpy impact test', 'Creep test, and nothing else'], correctIndex: 2, explanation: 'The Izod and Charpy impact tests are mechanical testing methods used to determine the impact resistance (toughness) of a material by measuring the energy absorbed in fracturing a notched specimen with a swinging pendulum hammer.', source },
  { id: 'rrb-je-c2-mec-084', section: 'Technical Abilities', topic: 'Engineering Mechanics', difficulty: 'medium', question: 'The distance from a given axis to a point at which the entire area (or mass) of a body may be assumed to be concentrated, without changing its moment of inertia about that axis, is called the:', options: ['Radius of gyration', 'Centroid', 'Centre of gravity only', 'Polar moment of inertia, exclusively'], correctIndex: 0, explanation: 'The radius of gyration is the distance from a given axis to a point at which the entire area (or mass) of a body may be assumed to be concentrated without changing its moment of inertia about that axis.', source },
  { id: 'rrb-je-c2-mec-085', section: 'Technical Abilities', topic: 'Strength of Materials', difficulty: 'medium', question: "A material that shows very little (or no) plastic deformation before fracturing under load, breaking suddenly with little or no warning, is generally described as:", options: ['Ductile', 'Malleable only', 'Elastic, exclusively', 'Brittle'], correctIndex: 3, explanation: 'A brittle material shows very little or no plastic deformation before fracturing under load, breaking suddenly with little or no visible warning, unlike a ductile material, which deforms noticeably before failure.', source },
  { id: 'rrb-je-c2-mec-086', section: 'Technical Abilities', topic: 'IC Engines', difficulty: 'medium', question: 'The maximum pressure developed inside an engine cylinder during combustion is measured using an instrument called a(n):', options: ['Tachometer', 'Dynamometer only, exclusively', 'Indicator (pressure-crank angle diagram device)', 'Manometer, and nothing else'], correctIndex: 2, explanation: 'An engine indicator is used to record the pressure developed inside the cylinder throughout the engine cycle (typically plotting pressure against volume or crank angle), from which the maximum pressure and indicated work can be determined.', source },
  { id: 'rrb-je-c2-mec-087', section: 'Technical Abilities', topic: 'IC Engines', difficulty: 'medium', question: 'A device used to measure the power output (brake power) of an engine or motor, typically by measuring the torque it produces against a controlled resisting load, is called a:', options: ['Dynamometer', 'Tachometer', 'Indicator only, exclusively', 'Manometer, and nothing else'], correctIndex: 0, explanation: 'A dynamometer is a device used to measure the power output (brake power) of an engine or motor, typically by measuring the torque produced against a controlled resisting load applied at a known speed.', source },
  { id: 'rrb-je-c2-mec-088', section: 'Technical Abilities', topic: 'Theory of Machines', difficulty: 'medium', question: 'The number of independent parameters (input motions) needed to completely specify the configuration/position of a kinematic chain or mechanism at any instant is called its:', options: ['Degrees of freedom', 'Number of links', 'Number of pairs, and nothing else', 'Kinematic inversion, exclusively'], correctIndex: 0, explanation: 'The degrees of freedom of a mechanism is the number of independent parameters (input motions) needed to completely specify its configuration at any instant, and this determines whether the mechanism is constrained, movable, or locked.', source },
  { id: 'rrb-je-c2-mec-089', section: 'Technical Abilities', topic: 'Theory of Machines', difficulty: 'medium', question: 'A mechanism in which the relative motion between the links is completely constrained, such that each link has only one definite path of motion relative to another, is called a:', options: ['Structure', 'Redundant mechanism, exclusively', 'Non-kinematic pair, and nothing else', 'Kinematic chain with complete constraint'], correctIndex: 3, explanation: 'A kinematic chain (or mechanism) with completely constrained motion is one in which each link has only one definite path of motion relative to another, ensuring predictable, determinate motion transfer throughout the mechanism.', source },
  { id: 'rrb-je-c2-mec-090', section: 'Technical Abilities', topic: 'Fluid Mechanics and Hydraulic Machines', difficulty: 'medium', question: 'The overall efficiency of a pump is defined as the ratio of the:', options: ['Input power to output (hydraulic) power', 'Discharge to the head developed', 'Output (hydraulic) power delivered to the fluid to the input (shaft) power supplied to the pump', 'Head developed to the discharge, and nothing else'], correctIndex: 2, explanation: "A pump's overall efficiency is defined as the ratio of the output (hydraulic) power actually delivered to the fluid to the input (shaft) power supplied to drive the pump, accounting for various internal losses.", source },
  { id: 'rrb-je-c2-mec-091', section: 'Technical Abilities', topic: 'Engineering Mechanics', difficulty: 'medium', question: "Lami's theorem, used to analyse the equilibrium of three concurrent, coplanar forces acting on a particle, states that each force is proportional to the:", options: ['Sine of the angle between the other two forces', 'Square of the angle between the other two forces', 'Cosine of the angle between the other two forces', 'Sum of the other two forces, and nothing else'], correctIndex: 0, explanation: "Lami's theorem states that, for three concurrent, coplanar forces in equilibrium, each force is proportional to the sine of the angle between the other two forces.", source },
  { id: 'rrb-je-c2-mec-092', section: 'Technical Abilities', topic: 'Strength of Materials', difficulty: 'medium', question: 'A pressure vessel or pipe whose wall thickness is small relative to its diameter (typically less than about 1/20th of the diameter) is generally classified, for stress-analysis purposes, as a:', options: ['Thick cylinder', 'Solid shaft, and nothing else', 'Composite beam, exclusively', 'Thin cylinder'], correctIndex: 3, explanation: 'A thin cylinder is one whose wall thickness is small relative to its internal diameter (typically less than about 1/20th of the diameter), allowing the assumption of uniform stress distribution across the wall thickness for analysis purposes.', source },
  { id: 'rrb-je-c2-mec-093', section: 'Technical Abilities', topic: 'Production Engineering', difficulty: 'medium', question: 'The process of removing a thin layer of material from a workpiece surface using a single-point or multi-point cutting tool, generally to achieve a desired shape, dimension, or finish, is broadly termed:', options: ['Casting', 'Forging only, exclusively', 'Machining', 'Welding, and nothing else'], correctIndex: 2, explanation: 'Machining is the broad category of manufacturing processes (including turning, milling, drilling, and grinding) that remove material from a workpiece using a cutting tool to achieve a desired shape, dimension, or surface finish.', source },
  { id: 'rrb-je-c2-mec-094', section: 'Technical Abilities', topic: 'Thermodynamics', difficulty: 'medium', question: 'The Zeroth Law of Thermodynamics forms the basis for the concept of:', options: ['Temperature measurement', 'Energy conservation', 'Entropy increase, exclusively', 'Work done by a system, and nothing else'], correctIndex: 0, explanation: 'The Zeroth Law of Thermodynamics states that if two bodies are each in thermal equilibrium with a third body, they are also in thermal equilibrium with each other, and it forms the fundamental basis for the concept of temperature and its measurement.', source },
  { id: 'rrb-je-c2-mec-095', section: 'Technical Abilities', topic: 'Refrigeration and Air Conditioning', difficulty: 'medium', question: 'The primary purpose of an air conditioning system, beyond simple cooling, is generally to control which combination of factors related to indoor air quality?', options: ['Temperature only, and nothing else', 'Only the pressure of the room', 'Only the colour temperature of indoor lighting', 'Temperature, humidity, air motion/circulation, and purity'], correctIndex: 3, explanation: 'An air conditioning system is designed to control multiple factors of indoor air quality together — temperature, humidity, air motion/circulation, and purity (cleanliness) — rather than temperature alone.', source },
  { id: 'rrb-je-c2-mec-096', section: 'Technical Abilities', topic: 'Theory of Machines', difficulty: 'medium', question: 'A device used to change the speed and/or torque of the output shaft relative to the input shaft, by combining gears of different sizes in a mechanical drive train, is generally known as a:', options: ['Coupling', 'Clutch only, exclusively', 'Gearbox (gear train)', 'Flywheel, and nothing else'], correctIndex: 2, explanation: 'A gearbox (gear train) is a mechanical assembly of gears used to change the speed and/or torque of an output shaft relative to an input shaft, commonly used in vehicles and industrial machinery drive trains.', source },
  { id: 'rrb-je-c2-mec-097', section: 'Technical Abilities', topic: 'Strength of Materials', difficulty: 'medium', question: 'The tendency of a beam or shaft to deflect (bend) laterally when it is not adequately supported, particularly under compressive or torsional loading beyond a critical value, is closely associated with the phenomenon of:', options: ['Buckling', 'Fatigue', 'Creep only, exclusively', 'Corrosion, and nothing else'], correctIndex: 0, explanation: 'Buckling is the sudden lateral deflection (instability) of a slender structural member, such as a column or unsupported beam, occurring when compressive or torsional loading exceeds a certain critical value.', source },
  { id: 'rrb-je-c2-mec-098', section: 'Technical Abilities', topic: 'IC Engines', difficulty: 'medium', question: 'The undesirable, abnormal combustion phenomenon in a spark-ignition petrol engine, characterised by a sharp metallic "pinging" sound caused by the premature auto-ignition of the unburned end-gas, is commonly known as:', options: ['Detonation (knocking)', 'Diesel knock only, exclusively', 'Backfiring, and nothing else', 'Misfiring only'], correctIndex: 0, explanation: 'Detonation (commonly called "knocking") in a spark-ignition petrol engine is an abnormal combustion phenomenon characterised by a sharp metallic "pinging" sound, caused by the premature auto-ignition of the unburned end-gas ahead of the advancing flame front.', source },
  { id: 'rrb-je-c2-mec-099', section: 'Technical Abilities', topic: 'Production Engineering', difficulty: 'medium', question: 'A low-temperature metal-joining process (compared to welding) that uses a filler metal with a melting point above 450°C (but below that of the base metals) to join two metal pieces without melting the base metals themselves, is called:', options: ['Soldering', 'Welding, exclusively', 'Riveting, and nothing else', 'Brazing'], correctIndex: 3, explanation: 'Brazing is a metal-joining process that uses a filler metal with a melting point above 450°C (but below that of the base metals being joined) to join the pieces without melting the base metals themselves, as distinct from soldering (which uses a lower-melting-point filler, generally below 450°C).', source },
  { id: 'rrb-je-c2-mec-100', section: 'Technical Abilities', topic: 'Engineering Mechanics', difficulty: 'medium', question: 'The branch of mechanics that deals with the motion of bodies without considering the forces that cause the motion is called:', options: ['Statics', 'Kinetics (dynamics) only', 'Dynamics only, and nothing else', 'Kinematics'], correctIndex: 3, explanation: 'Kinematics is the branch of mechanics concerned with describing the motion of bodies (displacement, velocity, acceleration) without considering the forces that cause that motion, as distinct from kinetics (or dynamics), which relates motion to the forces causing it.', source },
];
